            [4, 5, 6, 7],   // back face (z = 1)
            [0, 1, 5, 4],   // bottom face (y = -1)
            [2, 3, 7, 6],   // top face (y = 1)
            [0, 3, 7, 4],   // left face (x = -1)
            [1, 2, 6, 5]    // right face (x = 1)
        ];

