        // Set canvas size
        function resizeCanvas() {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        }
        resizeCanvas();
        window.addEventListener('resize', resizeCanvas);

        // Perspective projection
        function projectPoint([x, y, z]) {
            const d = projectionDistance;
            const f = Math.tan(fov / 2);
            const scale = (d * f) / (d + z);
            return [x * scale, y * scale];
        }

        // Backface culling - check if face is visible
        function isVisible(faceNormalsIdx, transformedNormals) {
            const normal = transformedNormals[faceNormalsIdx];
            // If normal's Z component (after projection) is positive, face is visible
            // Actually we check if the face normal dots with view direction (0,0,-1) is positive
            return normal[2] > 0;
