        // Rotate a point around X axis
        function rotateX(point, angle) {
            const [x, y, z] = point;
            const cos = Math.cos(angle);
            const sin = Math.sin(angle);
            return [
                x,
                y * cos - z * sin,
                y * sin + z * cos
            ];
        }

        // Rotate a point around Y axis
        function rotateY(point, angle) {
            const [x, y, z] = point;
            const cos = Math.cos(angle);
            const sin = Math.sin(angle);
            return [
                x * cos + z * sin,
                y,
                -x * sin + z * cos
            ];
        }

        // Rotate a point around Z axis
        function rotateZ(point, angle) {
            const [x, y, z] = point;
            const cos = Math.cos(angle);
            const sin = Math.sin(angle);
            return [
                x * cos - y * sin,
                x * sin + y * cos,
                z
            ];
        }

        // Apply all rotations to all vertices
        function rotateAllVertices(verts, rx, ry, rz) {
            return verts.map(v => rotateZ(rotateY(rotateX(v, rx), ry), rz));
        }

        // Compute transformed face normals
        function computeTransformedNormals(verts, rx, ry, rz) {
            // Apply same rotations to normals (without translation, which doesn't matter)
            const normals = [];
            for (let i = 0; i < faceNormals.length; i++) {
