            const maxX = Math.min(xMax, Math.max(...allX));
            const minY = Math.max(yMin, Math.min(...allY));
            const maxY = Math.min(yMax, Math.max(...allY));

            for (let y = minY; y <= maxY; y++) {
                for (let x = minX; x <= maxX; x++) {
                    const point = [x + 0.5, y + 0.5]; // Sample at pixel center
                    const [u, v, w] = barycentricCoords(point, [v1[0], v1[1]], [v2[0], v2[1]], [v3[0], v3[1]]);

                    if (u >= -0.001 && v >= -0.001 && w >= -0.001 && (u + v + w) <= 1 + 0.001) {
                        // Interpolate color
