                        const g = Math.max(0, Math.min(255, Math.round(interpolatedColor[1])));
                        const b = Math.max(0, Math.min(255, Math.round(interpolatedColor[2])));

                        ctx.fillStyle = `rgb(${r},${g},${b})`;
                        ctx.fillRect(x, y, 1, 1);
                    }
                }
            }
        }

