            const fpsElement = document.getElementById('fps');
            const pauseElement = document.getElementById('pause');
            const wireframeElement = document.getElementById('wireframe');

            // Process each face
            for (let faceIdx = 0; faceIdx < faceVertexIndices.length; faceIdx++) {
                const faceVerts = faceVertexIndices[faceIdx];

                // Get the 4 vertices of this face
                const face3D = faceVerts.map(idx => [...rotatedVerts[idx]]);

                // Check if face is visible (backface culling)
                if (!wireframe) {
                    const normal = transformedNormals[faceIdx];
                    // Simple check: if normal's Z component > 0, face is visible
                    // But we need to check after projection... let's use the original normal approach
                    // Project the first vertex to check visibility
                    const projected = projectPoint(face3D[0]);
                    // Actually let's use the proper backface culling: dot product of normal and view vector
                    // View vector is (0, 0, -1) - if dot(normal, view) > 0, face is facing us
                    // But we need the normal in view space. Since we're not translating, 
                    // the normal in world space dotted with (0,0,-1) tells us if it's facing us
                    if (normal[2] > 0) {
