                        // Triangle 2: vertices 0, 2, 3 of the face

                        // Triangle 1
                        const tri1 = [[0, 1, 2]];
                        // Triangle 2
                        const tri2 = [[0, 2, 3]];

                        // For each triangle, compute vertex colors and rasterize
                        const triangles = [tri1, tri2];

