                            const tris2D = triangle2D;
                            const minX = Math.min(...tris2D.map(t => t[0]));
                            const maxX = Math.max(...tris2D.map(t => t[0]));
                            const minY = Math.min(...tris2D.map(t => t[1]));
                            const maxY = Math.max(...tris2D.map(t => t[1]));

                            // Rasterize the triangle
                            rasterizeTriangle(rotatedVerts, vertexColors, tri, minX, maxX, minY, maxY);
