                    ctx.strokeStyle = '#00ff88';
                    ctx.lineWidth = 1;

                    for (let faceIdx = 0; faceIdx < faceVertexIndices.length; faceIdx++) {
                        const faceVerts = faceVertexIndices[faceIdx];
                        const face3D = faceVerts.map(idx => [...rotatedVerts[idx]]);

                        // Draw the 4 edges of each face
                        ctx.beginPath();
                        for (let i = 0; i < 4; i++) {
                            const v1 = face3D[i];
                            const v2 = face3D[(i + 1) % 4];
                            const p1 = projectPoint(v1);
                            const p2 = projectPoint(v2);
                            ctx.moveTo(p1[0], p1[1]);
                            ctx.lineTo(p2[0], p2[1]);
                        }
