            }

            // Display FPS
            fps = Math.round(1000 / (performance.now() - (window.lastRenderTime || performance.now())) + 1e-10);
            window.lastRenderTime = performance.now();
            fpsElement.textContent = fps;
            wireframeElement.textContent = wireframe ? 'On' : 'Off';
            pauseElement.textContent = animate ? 'On' : 'Off';
        }

        // Animation loop
        let lastTime = 0;
        function animateFrame(time) {
            if (!lastTime) lastTime = time;
            const delta = time - lastTime;
            lastTime = time;

            if (animate) {
                // Update light angle based on time
                lightAngle = (lightAngle + 0.001 * (delta / 16)) % (Math.PI * 2);
            }

            render();
            requestAnimationFrame(animateFrame);
